    name: "Index.html",
    filename: "Index.html",
    type: "html",
    description: "Templat HTML utama antaramuka Dapur KEMAS V1.00 responsif mudah alih dengan Tailwind CSS & Lucide Icons.",
    code: "<!DOCTYPE html>\n<html lang=\"ms\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Dapur KEMAS V1.00 - Unit PKK Perlis</title>\n  <!-- Tailwind CSS via CDN -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Lucide Icons -->\n  <script src=\"https://unpkg.com/lucide@latest\"></script>\n  <!-- html2canvas and jsPDF for 2-page PDF Cookbook Generation -->\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js\"></script>\n  <?!= include('css'); ?>\n</head>\n<body class=\"bg-[#0a0a0a] text-zinc-100 font-sans min-h-screen flex flex-col selection:bg-amber-500/30 selection:text-amber-200\">\n\n  <!-- Header Banner -->\n  <header class=\"border-b border-amber-900/30 bg-gradient-to-r from-zinc-950 via-zinc-900 to-zinc-950 px-4 py-3 sticky top-0 z-40 shadow-xl\">\n    <div class=\"max-w-7xl mx-auto flex items-center justify-between\">\n      <div class=\"flex items-center gap-3\">\n        <div class=\"p-2.5 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-400\">\n          <i data-lucide=\"utensils\" class=\"w-6 h-6\"></i>\n        </div>\n        <div>\n          <h1 class=\"text-lg font-bold text-amber-400 tracking-wide flex items-center gap-2\">\n            Dapur KEMAS <span class=\"text-[10px] px-2 py-0.5 rounded-full bg-amber-500/20 border border-amber-500/30 text-amber-300 font-mono\">V1.00</span>\n          </h1>\n          <p class=\"text-xs text-zinc-400 hidden sm:block\">Unit PKK KEMAS Negeri Perlis • Google Apps Script Powered</p>\n        </div>\n      </div>\n\n      <!-- Connection Status & Sync -->\n      <div class=\"flex items-center gap-3\">\n        <div id=\"status-indicator\" class=\"flex items-center gap-2 px-3 py-1 rounded-full text-xs bg-emerald-500/10 border border-emerald-500/30 text-emerald-400\">\n          <span class=\"w-2 h-2 rounded-full bg-emerald-400 animate-pulse\"></span>\n          <span id=\"status-text\" class=\"hidden sm:inline font-medium\">Google Sheet Connected</span>\n        </div>\n        <button onclick=\"refreshDataFromSheet()\" class=\"p-2 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 transition-colors cursor-pointer\" title=\"Muat Semula Data\">\n          <i data-lucide=\"refresh-cw\" class=\"w-4 h-4\"></i>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- Error Alert Toast Container -->\n  <div id=\"toast-container\" class=\"fixed top-16 right-4 z-50 max-w-sm space-y-2 pointer-events-none\"></div>\n\n  <!-- Main Dynamic Container -->\n  <main id=\"app-content\" class=\"flex-grow max-w-7xl w-full mx-auto px-4 py-6\">\n    <!-- Loading State with Fail-Safe Timeout Recovery -->\n    <div id=\"loading-spinner\" class=\"flex flex-col items-center justify-center py-20 text-center\">\n      <div class=\"w-12 h-12 border-4 border-amber-500/20 border-t-amber-500 rounded-full animate-spin mb-4\"></div>\n      <p class=\"text-zinc-300 font-bold text-sm\">Memuatkan Pangkalan Data Dapur KEMAS...</p>\n      <p class=\"text-xs text-zinc-500 mt-1\">Menghubung ke Google Sheet secara terus</p>\n      \n      <!-- Manual Bypass Button in case GAS connection takes time -->\n      <div class=\"mt-5 space-y-2\">\n        <button onclick=\"forceLoadLocalData()\" class=\"px-4 py-2 rounded-xl bg-amber-500/15 hover:bg-amber-500/25 border border-amber-500/30 text-amber-300 text-xs font-bold transition-all flex items-center gap-1.5 mx-auto cursor-pointer\">\n          <i data-lucide=\"zap\" class=\"w-3.5 h-3.5\"></i>\n          <span>Muat Terus Dengan Data Contoh KEMAS</span>\n        </button>\n        <p class=\"text-[11px] text-zinc-600\">Klik di atas jika skrin mengambil masa melebihi 5 saat</p>\n      </div>\n    </div>\n\n    <!-- Active View Area -->\n    <div id=\"view-area\" class=\"hidden\" style=\"display: none;\"></div>\n  </main>\n\n  <!-- Footer Navigation -->\n  <nav class=\"sticky bottom-0 bg-zinc-950 border-t border-zinc-800 px-4 py-2 z-40\">\n    <div class=\"max-w-md mx-auto flex justify-around\">\n      <button onclick=\"switchTab('dashboard')\" id=\"nav-dashboard\" class=\"flex flex-col items-center py-1 px-3 text-amber-400 font-bold transition-colors cursor-pointer\">\n        <i data-lucide=\"layout-dashboard\" class=\"w-5 h-5 mb-1\"></i>\n        <span class=\"text-xs\">Utama</span>\n      </button>\n      <button onclick=\"switchTab('recipes')\" id=\"nav-recipes\" class=\"flex flex-col items-center py-1 px-3 text-zinc-400 hover:text-amber-400 font-medium transition-colors cursor-pointer\">\n        <i data-lucide=\"book-open\" class=\"w-5 h-5 mb-1\"></i>\n        <span class=\"text-xs\">Resepi</span>\n      </button>\n      <button onclick=\"switchTab('add')\" id=\"nav-add\" class=\"flex flex-col items-center py-1 px-3 text-zinc-400 hover:text-amber-400 font-medium transition-colors cursor-pointer\">\n        <i data-lucide=\"plus-circle\" class=\"w-5 h-5 mb-1\"></i>\n        <span class=\"text-xs\">Tambah</span>\n      </button>\n      <button onclick=\"switchTab('settings')\" id=\"nav-settings\" class=\"flex flex-col items-center py-1 px-3 text-zinc-400 hover:text-amber-400 font-medium transition-colors cursor-pointer\">\n        <i data-lucide=\"settings\" class=\"w-5 h-5 mb-1\"></i>\n        <span class=\"text-xs\">Tetapan</span>\n      </button>\n    </div>\n  </nav>\n\n  <?!= include('JavaScript'); ?>\n  <script>\n    if (typeof lucide !== 'undefined') {\n      lucide.createIcons();\n    }\n  </script>\n</body>\n</html>\n"
